@prefix df:   <https://w3id.org/geolabs/ospd/data-formats/> .
@prefix dt:   <https://w3id.org/geolabs/ospd/data-types/> .
@prefix rim:  <https://w3id.org/ogc/rim/> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix dct:  <http://purl.org/dc/terms/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix prov: <http://www.w3.org/ns/prov#> .

<https://w3id.org/geolabs/ospd/data-formats/representation/eo-product-eo-geojson> a df:Representation, rim:RegisterItem ;
    dct:title "Earth observation product as EO GeoJSON"@en ;
    rim:objectIdentifier "https://w3id.org/geolabs/ospd/data-formats/representation/eo-product-eo-geojson"^^xsd:anyURI ;
    rim:itemClass df:representationItemClass ;
    rim:inRegister df:register ;
    rim:realizes <https://w3id.org/geolabs/ospd/data-types/data-type/eo-product/v1> ;
    df:format <https://w3id.org/geolabs/ospd/data-formats/format/eo-geojson> ;
    df:jsonSchemaFragment "{\"$ref\":\"https://schemas.opengis.net/eo-geojson/1.0/eo-geojson-schema.json#/definitions/EarthObservation\"}"^^rdf:JSON ;
    rim:validityStatus rim:invalid ;
    rim:publicationStatus rim:published ;
    rim:hasAction <https://w3id.org/geolabs/ospd/data-formats/representation/eo-product-eo-geojson/actions/addition> .

<https://w3id.org/geolabs/ospd/data-formats/representation/eo-product-eo-geojson/actions/addition> a rim:RegisterAction ;
    rim:actionType rim:additionAction ;
    rim:proposer df:geolabs ;
    rim:appliesTo <https://w3id.org/geolabs/ospd/data-formats/representation/eo-product-eo-geojson> ;
    prov:startedAtTime "2026-11-17T00:00:00Z"^^xsd:dateTime .
